def maximum_pair_sum_equal_digit_sum(nums):
    largest={};answer=-1
    for number in nums:
        key=sum(map(int,str(number)))
        if key in largest:answer=max(answer,number+largest[key])
        largest[key]=max(number,largest.get(key,0))
    return answer

